import{_ as n,o as a,c as p,am as e}from"./chunks/framework.CiF4W93w.js";const g=JSON.parse('{"title":"SpringSecurity学习使用","description":"","frontmatter":{"title":"SpringSecurity学习使用","excerpt":"SpringSecurity学习使用","date":"2024-03-31 11:16:30","updated":"2024-03-31 11:16:30"},"headers":[],"relativePath":"框架/企业开发框架/SpringSecurity/SpringSecurity学习使用.md","filePath":"框架/企业开发框架/SpringSecurity/SpringSecurity学习使用.md","lastUpdated":null}'),i={name:"框架/企业开发框架/SpringSecurity/SpringSecurity学习使用.md"};function l(t,s,r,o,c,u){return a(),p("div",null,[...s[0]||(s[0]=[e(`<p>没写完，后空可以看看若依，没空就算了。</p><h3 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h3><p>这里使用若依分离版项目： <a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">https://gitee.com/y_project/RuoYi-Vue</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#前端运行(以管理员身份运行)</span></span>
<span class="line"><span>npm install</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 强烈建议不要用直接使用 cnpm 安装，会有各种诡异的 bug，可以通过重新指定 registry 来解决 npm 安装速度慢的问题。</span></span>
<span class="line"><span>npm install --registry=https://registry.npmmirror.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 本地开发 启动项目</span></span>
<span class="line"><span>npm run dev</span></span></code></pre></div><p>后端配置</p><p>改一下数据库配置和服务器配置，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 开发环境配置</span></span>
<span class="line"><span>server:</span></span>
<span class="line"><span>  # 服务器的HTTP端口，默认为80</span></span>
<span class="line"><span>  port: 端口</span></span>
<span class="line"><span>  servlet:</span></span>
<span class="line"><span>    # 应用的访问路径</span></span>
<span class="line"><span>    context-path: /应用路径</span></span></code></pre></div><blockquote><p>关于 context-path 的配置说明</p></blockquote><p>如果你的服务器（或虚拟主机）<strong>只部署了一个应用</strong>，或者你希望应用直接响应域名根路径（例如，<code>http://www.example.com/</code>），你可以不设置上下文路径，即使用默认的根路径<code>/</code>。这种情况下，你可以在配置文件中省略<code>context-path</code>的设置。</p><p>如果服务器上部署了<strong>多个应用</strong>，或者出于其他原因（如API版本控制）需要将应用部署在非根路径下，就需要设置一个具体的上下文路径。这样做可以避免不同应用间的路由冲突，也使得URL具有更好的可读性和组织性。</p><hr><blockquote><p>报错：错误: 找不到或无法加载主类 com.ruoyi.RuoYiApplication</p></blockquote><p>解决：重新 clean ，再 install 一下，同时再加载前通过 父目录下的 Lifecycle 下进行 clean install；再重新加载依赖。</p><hr><blockquote><p>加密操作：</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public static String encryptPassword(String password)  </span></span>
<span class="line"><span>{  </span></span>
<span class="line"><span>    // 创建BCryptPasswordEncoder对象(用于密码加密的类)  </span></span>
<span class="line"><span>    BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();  </span></span>
<span class="line"><span>    return passwordEncoder.encode(password);  </span></span>
<span class="line"><span>}</span></span></code></pre></div><p>基于BCrypt算法的密码哈希机制；他提供的是一种单向的密码保护机制，旨在确保即使数据库被泄露，攻击者也无法恢复出用户的原始密码。这是目前Web应用中存储用户密码的推荐做法之一。</p><p>BCrypt算法会在每次加密时自动生成一个盐（Salt）【随机盐值】，并将盐值整合到最终的哈希结果中。这意味着即使两个用户使用了相同的密码，由于盐的随机性，他们存储在数据库中的哈希值也将是不同的。</p><blockquote><p>判定密码是否相同</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/**  </span></span>
<span class="line"><span> * 判断密码是否相同  </span></span>
<span class="line"><span> *  </span></span>
<span class="line"><span> * @param rawPassword 真实密码  </span></span>
<span class="line"><span> * @param encodedPassword 加密后字符  </span></span>
<span class="line"><span> * @return 结果  </span></span>
<span class="line"><span> */  </span></span>
<span class="line"><span>public static boolean matchesPassword(String rawPassword, String encodedPassword)  </span></span>
<span class="line"><span>{  </span></span>
<span class="line"><span>    BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();  </span></span>
<span class="line"><span>    return passwordEncoder.matches(rawPassword, encodedPassword);  </span></span>
<span class="line"><span>}</span></span></code></pre></div><p>matches 方法（提取盐操作，生成哈希值，比较哈希值）</p><ol><li><strong>提取盐值</strong>：<code>encodedPassword</code>（数据库中的哈希值）包括了原始密码哈希的结果和用于创建这个哈希的盐值。<code>matches</code>方法首先从<code>encodedPassword</code>中提取出用于哈希的盐值。</li><li><strong>重新哈希</strong>：使用提取出的盐值和同样的哈希算法（及其参数，如工作因子），对<code>rawPassword</code>（用户输入的密码）进行哈希处理。</li><li><strong>比较哈希值</strong>：将上一步生成的哈希值与<code>encodedPassword</code>进行比较。因为盐值是在原始密码哈希时随机生成的，并存储于<code>encodedPassword</code>中，所以即使是同一个密码，每次哈希的结果也是唯一的。但是，使用相同的密码和盐值，按照相同的方法进行哈希，将产生相同的哈希值。</li><li><strong>返回结果</strong>： <ul><li>如果两个哈希值相同，说明用户输入的密码正确，<code>matches</code>方法返回<code>true</code>。</li><li>如果两个哈希值不同，说明密码不匹配，<code>matches</code>方法返回<code>false</code>。</li></ul></li></ol><hr><h3 id="认证授权流程" tabindex="-1">认证授权流程 <a class="header-anchor" href="#认证授权流程" aria-label="Permalink to &quot;认证授权流程&quot;">​</a></h3><h3 id="一、常用用法" tabindex="-1">一、常用用法 <a class="header-anchor" href="#一、常用用法" aria-label="Permalink to &quot;一、常用用法&quot;">​</a></h3><p>引入使用，添加Spring Security依赖：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- Maven --&gt;</span></span>
<span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>    &lt;artifactId&gt;spring-boot-starter-security&lt;/artifactId&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>基本配置</p><p>默认情况下，Spring Security会添加一些自动配置，包括一个默认的用户（用户名是<code>user</code>，密码在启动时控制台输出）和基本的登录页面。</p><p>要自定义配置，你可以创建一个配置类并继承<code>WebSecurityConfigurerAdapter</code>，然后覆盖其中的方法</p><p>在若依的分离版本项目中，使用的配置类文件是： SecurityConfig</p><p>一般我们会 覆盖 configure 方法进行重写，添加一些自定义配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package com.ruoyi.framework.config;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>import org.springframework.beans.factory.annotation.Autowired;  </span></span>
<span class="line"><span>import org.springframework.context.annotation.Bean;  </span></span>
<span class="line"><span>import org.springframework.http.HttpMethod;  </span></span>
<span class="line"><span>import org.springframework.security.authentication.AuthenticationManager;  </span></span>
<span class="line"><span>import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;  </span></span>
<span class="line"><span>import org.springframework.security.config.annotation.method.configuration.EnableGlobalMethodSecurity;  </span></span>
<span class="line"><span>import org.springframework.security.config.annotation.web.builders.HttpSecurity;  </span></span>
<span class="line"><span>import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;  </span></span>
<span class="line"><span>import org.springframework.security.config.annotation.web.configurers.ExpressionUrlAuthorizationConfigurer;  </span></span>
<span class="line"><span>import org.springframework.security.config.http.SessionCreationPolicy;  </span></span>
<span class="line"><span>import org.springframework.security.core.userdetails.UserDetailsService;  </span></span>
<span class="line"><span>import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;  </span></span>
<span class="line"><span>import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;  </span></span>
<span class="line"><span>import org.springframework.security.web.authentication.logout.LogoutFilter;  </span></span>
<span class="line"><span>import org.springframework.web.filter.CorsFilter;  </span></span>
<span class="line"><span>import com.ruoyi.framework.config.properties.PermitAllUrlProperties;  </span></span>
<span class="line"><span>import com.ruoyi.framework.security.filter.JwtAuthenticationTokenFilter;  </span></span>
<span class="line"><span>import com.ruoyi.framework.security.handle.AuthenticationEntryPointImpl;  </span></span>
<span class="line"><span>import com.ruoyi.framework.security.handle.LogoutSuccessHandlerImpl;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>/**  </span></span>
<span class="line"><span> * spring security配置  </span></span>
<span class="line"><span> *   </span></span>
<span class="line"><span> * @author ruoyi  </span></span>
<span class="line"><span> */@EnableGlobalMethodSecurity(prePostEnabled = true, securedEnabled = true)  </span></span>
<span class="line"><span>public class SecurityConfig extends WebSecurityConfigurerAdapter  </span></span>
<span class="line"><span>{  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 自定义用户认证逻辑  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private UserDetailsService userDetailsService;  </span></span>
<span class="line"><span>      </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 认证失败处理类  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private AuthenticationEntryPointImpl unauthorizedHandler;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 退出处理类  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private LogoutSuccessHandlerImpl logoutSuccessHandler;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * token认证过滤器  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private JwtAuthenticationTokenFilter authenticationTokenFilter;  </span></span>
<span class="line"><span>      </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 跨域过滤器  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private CorsFilter corsFilter;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 允许匿名访问的地址  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Autowired  </span></span>
<span class="line"><span>    private PermitAllUrlProperties permitAllUrl;  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 解决 无法直接注入 AuthenticationManager  </span></span>
<span class="line"><span>     *     * @return     * @throws Exception  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Bean  </span></span>
<span class="line"><span>    @Override    public AuthenticationManager authenticationManagerBean() throws Exception  </span></span>
<span class="line"><span>    {  </span></span>
<span class="line"><span>        return super.authenticationManagerBean();  </span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * anyRequest          |   匹配所有请求路径  </span></span>
<span class="line"><span>     * access              |   SpringEl表达式结果为true时可以访问  </span></span>
<span class="line"><span>     * anonymous           |   匿名可以访问  </span></span>
<span class="line"><span>     * denyAll             |   用户不能访问  </span></span>
<span class="line"><span>     * fullyAuthenticated  |   用户完全认证可以访问（非remember-me下自动登录）  </span></span>
<span class="line"><span>     * hasAnyAuthority     |   如果有参数，参数表示权限，则其中任何一个权限可以访问  </span></span>
<span class="line"><span>     * hasAnyRole          |   如果有参数，参数表示角色，则其中任何一个角色可以访问  </span></span>
<span class="line"><span>     * hasAuthority        |   如果有参数，参数表示权限，则其权限可以访问  </span></span>
<span class="line"><span>     * hasIpAddress        |   如果有参数，参数表示IP地址，如果用户IP和参数匹配，则可以访问  </span></span>
<span class="line"><span>     * hasRole             |   如果有参数，参数表示角色，则其角色可以访问  </span></span>
<span class="line"><span>     * permitAll           |   用户可以任意访问  </span></span>
<span class="line"><span>     * rememberMe          |   允许通过remember-me登录的用户访问  </span></span>
<span class="line"><span>     * authenticated       |   用户登录后可访问  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Override  </span></span>
<span class="line"><span>    protected void configure(HttpSecurity httpSecurity) throws Exception  </span></span>
<span class="line"><span>    {  </span></span>
<span class="line"><span>        // 注解标记允许匿名访问的url  </span></span>
<span class="line"><span>        ExpressionUrlAuthorizationConfigurer&lt;HttpSecurity&gt;.ExpressionInterceptUrlRegistry registry = httpSecurity.authorizeRequests();  </span></span>
<span class="line"><span>        permitAllUrl.getUrls().forEach(url -&gt; registry.antMatchers(url).permitAll());  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>        httpSecurity  </span></span>
<span class="line"><span>                // CSRF禁用，因为不使用session  </span></span>
<span class="line"><span>                .csrf().disable()  </span></span>
<span class="line"><span>                // 禁用HTTP响应标头  </span></span>
<span class="line"><span>                .headers().cacheControl().disable().and()  </span></span>
<span class="line"><span>                // 认证失败处理类  </span></span>
<span class="line"><span>                .exceptionHandling().authenticationEntryPoint(unauthorizedHandler).and()  </span></span>
<span class="line"><span>                // 基于token，所以不需要session  </span></span>
<span class="line"><span>                .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS).and()  </span></span>
<span class="line"><span>                // 过滤请求  </span></span>
<span class="line"><span>                .authorizeRequests()  </span></span>
<span class="line"><span>                // 对于登录login 注册register 验证码captchaImage 允许匿名访问  </span></span>
<span class="line"><span>                .antMatchers(&quot;/login&quot;, &quot;/register&quot;, &quot;/captchaImage&quot;).permitAll()  </span></span>
<span class="line"><span>                // 静态资源，可匿名访问  </span></span>
<span class="line"><span>                .antMatchers(HttpMethod.GET, &quot;/&quot;, &quot;/*.html&quot;, &quot;/**/*.html&quot;, &quot;/**/*.css&quot;, &quot;/**/*.js&quot;, &quot;/profile/**&quot;).permitAll()  </span></span>
<span class="line"><span>                .antMatchers(&quot;/swagger-ui.html&quot;, &quot;/swagger-resources/**&quot;, &quot;/webjars/**&quot;, &quot;/*/api-docs&quot;, &quot;/druid/**&quot;).permitAll()  </span></span>
<span class="line"><span>                // 除上面外的所有请求全部需要鉴权认证  </span></span>
<span class="line"><span>                .anyRequest().authenticated()  </span></span>
<span class="line"><span>                .and()  </span></span>
<span class="line"><span>                .headers().frameOptions().disable();  </span></span>
<span class="line"><span>        // 添加Logout filter  </span></span>
<span class="line"><span>        httpSecurity.logout().logoutUrl(&quot;/logout&quot;).logoutSuccessHandler(logoutSuccessHandler);  </span></span>
<span class="line"><span>        // 添加JWT filter  </span></span>
<span class="line"><span>        httpSecurity.addFilterBefore(authenticationTokenFilter, UsernamePasswordAuthenticationFilter.class);  </span></span>
<span class="line"><span>        // 添加CORS filter  </span></span>
<span class="line"><span>        httpSecurity.addFilterBefore(corsFilter, JwtAuthenticationTokenFilter.class);  </span></span>
<span class="line"><span>        httpSecurity.addFilterBefore(corsFilter, LogoutFilter.class);  </span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 强散列哈希加密实现  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Bean  </span></span>
<span class="line"><span>    public BCryptPasswordEncoder bCryptPasswordEncoder()  </span></span>
<span class="line"><span>    {  </span></span>
<span class="line"><span>        return new BCryptPasswordEncoder();  </span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>    /**  </span></span>
<span class="line"><span>     * 身份认证接口  </span></span>
<span class="line"><span>     */  </span></span>
<span class="line"><span>    @Override  </span></span>
<span class="line"><span>    protected void configure(AuthenticationManagerBuilder auth) throws Exception  </span></span>
<span class="line"><span>    {  </span></span>
<span class="line"><span>        auth.userDetailsService(userDetailsService).passwordEncoder(bCryptPasswordEncoder());  </span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="二、权限控制" tabindex="-1">二、权限控制 <a class="header-anchor" href="#二、权限控制" aria-label="Permalink to &quot;二、权限控制&quot;">​</a></h3>`,34)])])}const h=n(i,[["render",l]]);export{g as __pageData,h as default};
